async function e(e){await new Promise(t=>{window.setTimeout(t,Math.max(e,0))})}async function t(t,{timeoutMs:n=5e3,intervalMs:r=30}={}){let i=Date.now();for(;Date.now()-i<n;){let n=t();if(n)return n;await e(r)}throw Error(`Timed out waiting for async condition.`)}function n(e,t){let n=null;return(...r)=>{n!==null&&window.clearTimeout(n),n=window.setTimeout(()=>{e(...r)},Math.max(t,0))}}export{e as n,t as r,n as t};